import 'package:fastway/features/home/domain/entities/product_entity.dart';
import 'package:fastway/features/home/presentation/widget/card/product_card.dart';
import 'package:flutter/material.dart';

class ProductsRow extends StatelessWidget {
  final List<ProductEntity> products;
  final void Function(String name, String id)? onTap;

  const ProductsRow({super.key, required this.products, this.onTap});

  @override
  Widget build(BuildContext context) {
    final w = MediaQuery.sizeOf(context).width;

    // Card width — responsive, clamped
    final cardW = (w * 0.42).clamp(140.0, 190.0);

    // Height = square image + info area (no overflow)
    // image = cardW, info area ≈ 130 px is enough for name+rating+price+stock
    final cardH = cardW + 130.0;

    return SizedBox(
      height: cardH,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: 16),
        itemCount: products.length,
        separatorBuilder: (_, __) => const SizedBox(width: 12),
        itemBuilder: (_, i) {
          final p = products[i];
          return SizedBox(
            width: cardW,
            child: ProductCard(
              productId: p.id,
              name: p.name,
              imageUrl: p.imageUrl,
              price: p.price,
              originalPrice: p.originalPrice,
              rating: p.rating,
              reviewCount: p.reviewCount,
              isNew: p.isNew,
              isAvailable: p.isAvailable,
              isExpressEligible: p.isExpressEligible,
              isFeatured: p.isFeatured,
              stockWarning: p.stockWarning,
              pointsToEarn: p.pointsToEarn,
